export async function loadClients(): Promise<Client[]> {
  const paths = [
    'company_dropdown_options.csv',
    '/company_dropdown_options.csv',
    './company_dropdown_options.csv'
  ];

  for (const path of paths) {
    try {
      console.log(`Attempting to read CSV from: ${path}`);
      const response = await window.fs.readFile(path, { encoding: 'utf8' });
      
      return new Promise((resolve) => {
        Papa.parse(response, {
          header: true,
          skipEmptyLines: true,
          complete: (results) => {
            console.log('CSV parse results:', {
              fields: results.meta.fields,
              rowCount: results.data.length
            });
            
            // Map the data to our Client interface
            // Try to find the company name column
            const nameColumn = results.meta.fields?.find(field => 
              ['company', 'company_name', 'name', 'client', 'client_name']
                .includes(field.toLowerCase())
            );

            if (!nameColumn || !results.data.length) {
              console.warn('Using default client data - could not find valid company names in CSV');
              clientsData = defaultClients;
            } else {
              clientsData = results.data
                .map((row: any, index) => ({
                  id: index + 1,
                  name: String(row[nameColumn]).trim()
                }))
                .filter(client => client.name);
            }

            console.log('Final processed clients:', clientsData.slice(0, 3));
            resolve(clientsData);
          },
          error: (error) => {
            console.warn('CSV parsing error:', error);
            console.log('Falling back to default clients');
            clientsData = defaultClients;
            resolve(clientsData);
          }
        });
      });
    } catch (error) {
      console.log(`Failed to read from ${path}:`, error);
      // Continue to next path
    }
  }

  // If we get here, none of the paths worked
  console.warn('Could not load CSV file, using default clients');
  clientsData = defaultClients;
  return clientsData;
}

export function getClients(): Client[] {
  return clientsData.length > 0 ? clientsData : defaultClients;
}